  const riSec=ri?parseFloat(String(ri.retryDelay||'').replace(/s$/,'')):NaN;
  const hintSec=Number.isFinite(riSec)&&riSec>0?riSec:(Number.isFinite(ra)&&ra>0?ra:0);
  return Math.max(hintSec?Math.min(hintSec,60)*1000:0,exp);
}
